let commonsData={modules:[],pins:[]};
const beforeCommons=render;
render=function(){if(location.hash!=='#curriculum-commons')return beforeCommons();document.getElementById('app').innerHTML=integratedShell('curriculum-commons',heading('Curriculum Commons','Scholarion Academy · Versioned instructor drafts')+`<section class="card prose"><p>Shared designs are explicitly pinned to programs. New versions never replace existing pins automatically. All content remains draft.</p><p id="commons-status" role="status">Connecting…</p><label>Authorized course context<select id="commons-scope"></select></label><button class="button" id="commons-load">Load shared module mappings</button> <a href="#program-studio">Program design studio and exports</a></section><div id="commons-list"></div>`,model.role);bind();normalizeWorkspace();loadCommons();};
async function loadCommons(){try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';commonsData=await workspaceApi('commons/list');if(location.hash!=='#curriculum-commons')return;document.getElementById('commons-scope').innerHTML=workspaceSession.courses.map(c=>`<option ${c===selectedCourse?'selected':''}>${esc(c)}</option>`).join('');const latest=commonsData.modules.filter((m,i,a)=>a.findIndex(x=>x.module===m.module)===i);document.getElementById('commons-status').textContent=`${latest.length} shared modules; ${commonsData.pins.length} explicit program pins. Publication disabled.`;document.getElementById('commons-list').innerHTML=latest.map(m=>{const versions=commonsData.modules.filter(x=>x.module===m.module),pins=commonsData.pins.filter(x=>x.module===m.module);return `<section class="card prose"><h2>${esc(m.title)}</h2><p>${esc(m.module)} · Latest draft v${m.version}</p><details><summary>Review and revise shared design</summary><form data-commons-revise="${esc(m.module)}" data-version="${m.version}"><label>Title<input name="title" maxlength="200" required value="${esc(m.title)}"></label><label>Original design and evidence references<textarea name="body" rows="5" maxlength="12000" required>${esc(m.body)}</textarea></label><button class="button">Save new immutable version</button></form></details><details><summary>Version history</summary>${versions.map(v=>`<h3>Version ${v.version}</h3><p style="white-space:pre-wrap">${esc(v.body)}</p>`).join('')}</details><h3>Program selections</h3><ul>${pins.map(p=>`<li>Program #${p.program}: v${p.version} (selection revision ${p.revision})${p.version<m.version?' — newer draft available; review before upgrading':''}</li>`).join('')||'<li>No program has selected this module.</li>'}</ul><form data-commons-pin="${esc(m.module)}"><label>Program<select name="program">${m.programs.filter(n=>n>=1&&n<=25).map(n=>`<option value="${n}">#${n}</option>`).join('')}</select></label><label>Version<select name="version">${versions.map(v=>`<option value="${v.version}">v${v.version}</option>`).join('')}</select></label><button class="button secondary">Pin selected version to program draft</button></form><p>Load the program shells first. Pins are course-scoped design references, not credit awards or live course updates.</p></section>`;}).join('');}catch(e){const n=document.getElementById('commons-status');if(n)n.textContent=e.message+' — An authorized instructor session is required.';}}
document.addEventListener('change',e=>{if(e.target.id==='commons-scope'){selectedCourse=e.target.value;loadCommons();}});
document.addEventListener('click',async e=>{if(e.target.id!=='commons-load')return;try{e.target.disabled=true;await workspaceApi('commons/load');await loadCommons();}catch(err){document.getElementById('commons-status').textContent=err.message;}finally{e.target.disabled=false;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('[data-commons-revise],[data-commons-pin]'))return;e.preventDefault();const b=f.querySelector('button'),d=new FormData(f);b.disabled=true;try{if(f.dataset.commonsRevise)await workspaceApi('commons/revise',{module:f.dataset.commonsRevise,version:Number(f.dataset.version),title:d.get('title'),body:d.get('body')});else{const program=Number(d.get('program')),module=f.dataset.commonsPin,p=commonsData.pins.find(x=>x.program===program&&x.module===module);await workspaceApi('commons/pin',{module,program,version:Number(d.get('version')),revision:p?p.revision:0});}await loadCommons();}catch(err){document.getElementById('commons-status').textContent=err.message;}finally{b.disabled=false;}});
render();
